                   </button>
               </div>
               {searchError && <p className="text-xs text-rose-500 font-bold mt-2 ml-1">{searchError}</p>}
           </div>

           <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar-hover">
               {conversations.map(conv => {
