  const handlePaste = async (e: React.ClipboardEvent) => {
      const items = e.clipboardData.items;
      const files: File[] = [];
      for (let i = 0; i < items.length; i++) {
          if (items[i].type.indexOf('image') !== -1) {
              const blob = items[i].getAsFile();
              if (blob) files.push(blob);
          }
      }
      if (files.length > 0) {
          e.preventDefault();
          processFiles(files);
      }
  };

