      // Trigger upload for each new image
      newImages.forEach(async (img) => {
          try {
              const result = await apiService.uploadFile(img.file);
              setPendingImages(prev => prev.map(p => 
                  p.id === img.id ? { ...p, serverUrl: result.url, uploading: false } : p
              ));
