           const db = getLocalDB();
           if(db.notifications) {
               db.notifications.forEach((n: any) => {
                   if(n.userId === 'all' || n.userId === userId) {
                       if(!n.readBy) n.readBy = [];
                       if(!n.readBy.includes(userId)) n.readBy.push(userId);
                   }
               });
               saveLocalDB(db);
           }
      }
  },

  createSystemNotification: async (notification: any) => {
