              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ userId, message, botName, sessionId })
          });
          if (!res.ok) throw new Error("Chat failed");
          const data = await res.json();
          return data.text;
      } catch (e) {
          console.error(e);
          throw e;
      }
