    } else {
        filter = {
            $and: [
                { $or: [{ userId: 'all' }, { userId: userId }] },
                { 
                    $or: [
                        { scheduledAt: { $lte: now + 60000 } },
                        { time: { $lte: now + 60000 } },
                        { scheduledAt: { $exists: false } }
                    ] 
                }
            ]
        };
    }

    const notifs = await Notification.find(filter).sort({ scheduledAt: -1, time: -1 }).limit(50).lean();
