};

// Specialized Standalone Widget Component for Embed Mode
const StandaloneChatWidget: React.FC<{ settings: WidgetSettings, userId: string }> = ({ settings, userId }) => {
    const [isOpen, setIsOpen] = useState(false);
    const [plugins, setPlugins] = useState<PluginConfig | null>(null);

    // Fetch Plugins at the top level to control Auto Open from here
    useEffect(() => {
        const fetchPlugins = async () => {
            try {
                const data = await apiService.getPlugins(userId);
                setPlugins(data);

                // Handle Auto Open logic here in the container
                if (data.autoOpen?.enabled) {
                    setTimeout(() => setIsOpen(true), data.autoOpen.delay * 1000);
                }
            } catch (e) {
                console.error("Failed to load plugins in embed mode", e);
            }
        };
        fetchPlugins();
    }, [userId]);

    useEffect(() => {
        // Communicate state change to parent window (widget.js)
        window.parent.postMessage(isOpen ? 'bibichat-open' : 'bibichat-close', '*');

        // Always enforce position when state changes or loads
        setTimeout(() => {
             window.parent.postMessage({ type: 'bibichat-position', position: settings.position }, '*');
        }, 100);

    }, [isOpen, settings.position]);

    const alignClass = settings.position === 'left' ? 'items-start' : 'items-end';

    return (
        <div className={`h-full w-full flex flex-col justify-end ${alignClass} p-0 sm:p-4 bg-transparent pointer-events-auto`}>
            {isOpen && (
                <div className="w-full h-full flex flex-col relative z-20 animate-in slide-in-from-bottom-5 fade-in duration-300">
                    <ChatWidget 
                        settings={settings} 
                        userId={userId} 
                        forceOpen={true} 
                        onClose={() => setIsOpen(false)} 
                        isEmbed={true}
                        initialPlugins={plugins} // Pass fetched plugins down to avoid refetch/delay
                    />
                </div>
            )}
            {!isOpen && (
                 <button 
                    onClick={() => setIsOpen(true)} 
                    className="w-14 h-14 rounded-full shadow-2xl flex items-center justify-center text-white text-2xl transition-all hover:scale-110 active:scale-95 duration-300 relative group z-20 border-2 border-white/20 m-2 sm:m-0 pointer-events-auto" 
                    style={{ backgroundColor: settings.primaryColor || '#8b5cf6' }}
                >
                    <span className="absolute inset-0 rounded-full bg-white opacity-20 group-hover:animate-ping"></span>
                    <i className="fa-solid fa-comment-dots"></i>
                </button>
            )}
        </div>
    );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { WidgetSettings, Message, User, PluginConfig } from '../types';
import { apiService } from '../services/apiService';

interface Props {
  settings: WidgetSettings;
  userId: string;
  forceOpen?: boolean; // New Prop for Embed Mode
  onClose?: () => void; // New Prop for Embed Mode
  isEmbed?: boolean; // New Prop to adjust layout
  initialPlugins?: PluginConfig | null; // Pass plugins from parent to avoid double fetch/logic split
}

const ChatWidget: React.FC<Props> = ({ settings, userId, forceOpen, onClose, isEmbed, initialPlugins }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', role: 'model', text: settings.welcomeMessage, timestamp: Date.now() }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const [sessionId, setSessionId] = useState('');

  // Plugin States
  const [plugins, setPlugins] = useState<any>(initialPlugins || null);
  const [showLeadForm, setShowLeadForm] = useState(false);
  const [leadForm, setLeadForm] = useState({ name: '', phone: '', email: '' });
  const [leadSubmitted, setLeadSubmitted] = useState(false);

  // Sync internal state with external forceOpen prop
  useEffect(() => {
      if (forceOpen !== undefined) setIsOpen(forceOpen);
  }, [forceOpen]);

  // Initialize Session ID & Fetch Plugins (if not provided)
  useEffect(() => {
    // 1. Session Logic
    let storedSessionId = localStorage.getItem('bibichat_session_id');
    if (!storedSessionId) {
        storedSessionId = Math.random().toString(36).substring(2) + Date.now().toString(36);
        localStorage.setItem('bibichat_session_id', storedSessionId);
    }
    setSessionId(storedSessionId);

    // 2. Plugins Logic
    if (!plugins) {
        const fetchPlugins = async () => {
            const p = await apiService.getPlugins(userId);
            setPlugins(p);

            // Auto Open Logic - Only if not forced (embed mode handles its own open state usually via button, but autoOpen can trigger it too)
            // NOTE: Embed mode auto-open is now handled in StandaloneChatWidget (App.tsx)
            if (p.autoOpen?.enabled && !isEmbed) {
                setTimeout(() => setIsOpen(true), p.autoOpen.delay * 1000);
            }
        };
        fetchPlugins();
    }
  }, [userId, isEmbed]);

  // Effect to scroll bottom
  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, isLoading, showLeadForm]);

  useEffect(() => {
    if (messages.length === 1 && messages[0].id === '1') {
      setMessages([{ ...messages[0], text: settings.welcomeMessage }]);
    }
  }, [settings.welcomeMessage]);

  // Handle Auto-show Lead Form when opened
  useEffect(() => {
      if (isOpen && plugins?.leadForm?.enabled && plugins?.leadForm?.trigger === 'on_open' && !leadSubmitted && !showLeadForm) {
          setShowLeadForm(true);
      }
