      if (!res.ok) throw new Error("Lỗi máy chủ");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      db.users = db.users.filter((u: any) => u.id !== targetUserId);
      saveLocalDB(db);
      return { success: true, message: "Xóa thành công (Chế độ Offline)" };
