                       </div>
                   </div>

                   {/* Messages List */}
                   <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-slate-50 dark:bg-slate-900" ref={scrollRef}>
                       {groupedMessages.map((item) => {
