               </div>
           )}
       </div>
    </div>

    {lightboxData && (
        <ImageLightbox 
            images={lightboxData.images}
            initialIndex={lightboxData.index}
            onClose={() => setLightboxData(null)}
        />
    )}
    </>
  );
};

