// Improved SafeImage
const SafeImage: React.FC<{ src: string; alt: string; className?: string; onClick?: () => void; onImageLoaded?: () => void }> = ({ src, alt, className, onClick, onImageLoaded }) => {
    const [isLoaded, setIsLoaded] = useState(false);
