  maxPoolSize: 100, // High concurrency connection pool
  serverSelectionTimeoutMS: 5000,
  socketTimeoutMS: 45000,
} as any)
  .then(() => console.log('✅ Đã kết nối cơ sở dữ liệu thành công!'))
