    } catch (e) {
      const db = getLocalDB();
      db.documents = db.documents.filter((d: any) => d.id !== id);
      saveLocalDB(db);
    }
  },

  // --- ANALYTICS & LOGS (PAGINATED CHAT - HYBRID ONLINE/OFFLINE) ---

  getChatSessionsPaginated: async (userId: string | 'all', page: number, limit: number, filterUserId: string = 'all'): Promise<{ data: any[], pagination: any }> => {
      try {
          const res = await fetch(`${API_URL}/api/chat-sessions/${userId}?page=${page}&limit=${limit}&filterUserId=${filterUserId}`);
          if(!res.ok) throw new Error("Lỗi tải danh sách chat");
          return await res.json();
      } catch (e) {
          const db = getLocalDB();
          let allLogs = db.chatLogs || [];

          if (userId !== 'all') {
              allLogs = allLogs.filter((l: any) => l.userId === userId);
          } else {
              if (filterUserId !== 'all') {
                  allLogs = allLogs.filter((l: any) => l.userId === filterUserId);
              }
          }

          const sessionsMap: Record<string, any> = {};
          allLogs.forEach((log: any) => {
              const sessId = log.customerSessionId || 'legacy_session';
              const key = `${log.userId}_${sessId}`; 
              if (!sessionsMap[key]) {
                  sessionsMap[key] = {
                      uniqueKey: key,
                      sessionId: sessId,
                      userId: log.userId,
                      lastActive: log.timestamp,
                      preview: log.query,
                      messageCount: 0
                  };
              }
              sessionsMap[key].messageCount++;
              if (log.timestamp > sessionsMap[key].lastActive) {
                  sessionsMap[key].lastActive = log.timestamp;
                  sessionsMap[key].preview = log.query;
              }
          });

          const sessions = Object.values(sessionsMap).sort((a: any, b: any) => b.lastActive - a.lastActive);
          const total = sessions.length;
          const startIndex = (page - 1) * limit;

          return { 
              data: sessions.slice(startIndex, startIndex + limit), 
              pagination: { 
                  total, 
                  page, 
                  limit, 
                  totalPages: Math.ceil(total / limit) 
              }
          };
      }
  },

  getChatMessages: async (userId: string | 'all', sessionId: string): Promise<ChatLog[]> => {
      try {
          const res = await fetch(`${API_URL}/api/chat-messages/${userId}/${sessionId}`);
          if(!res.ok) throw new Error("Lỗi tải tin nhắn");
          return await res.json();
      } catch (e) {
          const db = getLocalDB();
          let logs = db.chatLogs || [];
          if (userId !== 'all' && userId !== 'admin') {
              logs = logs.filter((l: any) => l.userId === userId);
          }
          return logs.filter((l: any) => l.customerSessionId === sessionId)
                     .sort((a: any, b: any) => a.timestamp - b.timestamp);
      }
  },

  // --- STATS ---
  getStats: async (userId: string | 'all', period: string): Promise<any[]> => {
      try {
          const res = await fetch(`${API_URL}/api/chat-logs/${userId}`);
          if (!res.ok) throw new Error("Failed to fetch logs for stats");
          const logs: ChatLog[] = await res.json();

          const now = Date.now();
          let startTime = 0;

          if (period === 'hour') startTime = now - 60 * 60 * 1000;
          else if (period === 'day') startTime = now - 24 * 60 * 60 * 1000;
          else if (period === 'week') startTime = now - 7 * 24 * 60 * 60 * 1000;
          else startTime = now - 30 * 24 * 60 * 60 * 1000;

          const filteredLogs = logs.filter(l => l.timestamp >= startTime);

          const groups: Record<string, { count: number, timestamp: number }> = {};

          filteredLogs.forEach(log => {
              const date = new Date(log.timestamp);
              let label = '';
              let sortKey = 0;

              if (period === 'hour') {
                  const minutes = Math.floor(date.getMinutes() / 5) * 5;
                  const d = new Date(date);
                  d.setMinutes(minutes, 0, 0);
                  label = `${d.getHours().toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}`;
                  sortKey = d.getTime();
              } else if (period === 'day') {
                  const h = date.getHours();
                  label = `${h.toString().padStart(2, '0')}:00`;
                  const d = new Date(date);
                  d.setMinutes(0, 0, 0);
                  sortKey = d.getTime();
              } else if (period === 'week') {
                  label = `${date.getDate().toString().padStart(2, '0')}/${(date.getMonth() + 1).toString().padStart(2, '0')}`;
                  const d = new Date(date);
                  d.setHours(0, 0, 0, 0);
                  sortKey = d.getTime();
              } else {
                  label = `${date.getDate().toString().padStart(2, '0')}/${(date.getMonth() + 1).toString().padStart(2, '0')}`;
                  const d = new Date(date);
                  d.setHours(0, 0, 0, 0);
                  sortKey = d.getTime();
              }

              if (!groups[label]) {
                  groups[label] = { count: 0, timestamp: sortKey };
              }
              groups[label].count++;
          });

          return Object.entries(groups)
            .map(([label, data]) => ({
              label,
              queries: data.count,
              solved: data.count,
              timestamp: data.timestamp
            }))
            .sort((a, b) => a.timestamp - b.timestamp);

      } catch (e) {
          return [];
      }
  },

  // --- CHAT WIDGET ---
  chat: async (userId: string, message: string, botName: string, sessionId: string): Promise<string> => {
      try {
          const res = await fetch(`${API_URL}/api/chat`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ userId, message, botName, sessionId })
          });
          if (!res.ok) throw new Error("Chat failed");
          const data = await res.json();
          return data.text;
      } catch (e) {
          console.error(e);
          throw e;
      }
  },

  // --- NOTIFICATIONS ---
  getNotifications: async (userId: string): Promise<Notification[]> => {
      try {
          const res = await fetch(`${API_URL}/api/notifications/${userId}`);
          if (!res.ok) throw new Error("Failed");
          return await res.json();
      } catch (e) {
          const db = getLocalDB();
          return (db.notifications || []).filter((n: any) => n.userId === 'all' || n.userId === userId).map((n: any) => ({...n, isRead: (n.readBy||[]).includes(userId)}));
      }
  },

  markNotificationRead: async (id: string, userId: string) => {
      try {
          await fetch(`${API_URL}/api/notifications/${id}/read`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ userId })
          });
      } catch (e) {
          const db = getLocalDB();
          const n = db.notifications?.find((x: any) => x.id === id);
          if(n) {
              if(!n.readBy) n.readBy = [];
              if(!n.readBy.includes(userId)) n.readBy.push(userId);
              saveLocalDB(db);
          }
      }
  },

  markAllNotificationsRead: async (userId: string) => {
      try {
          await fetch(`${API_URL}/api/notifications/read-all`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ userId })
          });
      } catch (e) {
           const db = getLocalDB();
           if(db.notifications) {
               db.notifications.forEach((n: any) => {
                   if(n.userId === 'all' || n.userId === userId) {
                       if(!n.readBy) n.readBy = [];
                       if(!n.readBy.includes(userId)) n.readBy.push(userId);
                   }
               });
               saveLocalDB(db);
           }
      }
  },

  createSystemNotification: async (notification: any) => {
      try {
          await fetch(`${API_URL}/api/notifications/create`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(notification)
          });
      } catch (e) {
          const db = getLocalDB();
          if(!db.notifications) db.notifications = [];
          db.notifications.push({ ...notification, id: Date.now().toString(), readBy: [] });
          saveLocalDB(db);
      }
  },

  suggestIcon: async (context: string): Promise<string> => {
      if (!process.env.API_KEY) return 'fa-bell';
      try {
          const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
          const response = await ai.models.generateContent({
              model: 'gemini-3-flash-preview',
              contents: `Suggest a single FontAwesome 6 icon class (e.g., fa-bell) for: "${context}". Return ONLY the class name.`,
          });
          return response.text?.trim() || 'fa-bell';
      } catch (e) {
          return 'fa-bell';
      }
  }
};

import { io, Socket } from 'socket.io-client';

// Use the same URL logic as apiService
const SERVER_URL = process.env.SERVER_URL || 'https://api.bibichat.me';

class SocketService {
  private socket: Socket | null = null;

  connect(userId: string) {
    if (this.socket) return;

    this.socket = io(SERVER_URL, {
      query: { userId },
      transports: ['websocket'], // Force websocket to reduce HTTP overhead
      reconnectionAttempts: 5,
      reconnectionDelay: 1000,
    });

    this.socket.on('connect', () => {
      console.log('⚡ Connected to Real-time Server');
    });

    this.socket.on('disconnect', () => {
      console.log('🔌 Disconnected from Real-time Server');
    });
  }

  disconnect() {
    if (this.socket) {
      this.socket.disconnect();
      this.socket = null;
    }
  }

  // Generic event listener
  on(event: string, callback: (data: any) => void) {
    if (!this.socket) return;
    this.socket.on(event, callback);
  }

  // Generic event emitter
  emit(event: string, data: any) {
    if (!this.socket) return;
    this.socket.emit(event, data);
  }

  off(event: string) {
    if (!this.socket) return;
    this.socket.off(event);
  }
}

export const socketService = new SocketService();

import React, { useState, useRef, useEffect } from 'react';
import { WidgetSettings, Message, User, PluginConfig } from '../types';
import { apiService } from '../services/apiService';

interface Props {
  settings: WidgetSettings;
  userId: string;
  forceOpen?: boolean; // New Prop for Embed Mode
  onClose?: () => void; // New Prop for Embed Mode
  isEmbed?: boolean; // New Prop to adjust layout
  initialPlugins?: PluginConfig | null; // Pass plugins from parent to avoid double fetch/logic split
}

const ChatWidget: React.FC<Props> = ({ settings, userId, forceOpen, onClose, isEmbed, initialPlugins }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', role: 'model', text: settings.welcomeMessage, timestamp: Date.now() }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const [sessionId, setSessionId] = useState('');

  // Plugin States
  const [plugins, setPlugins] = useState<any>(initialPlugins || null);
  const [showLeadForm, setShowLeadForm] = useState(false);
  const [leadForm, setLeadForm] = useState({ name: '', phone: '', email: '' });
  const [leadSubmitted, setLeadSubmitted] = useState(false);

  // Sync internal state with external forceOpen prop
  useEffect(() => {
      if (forceOpen !== undefined) setIsOpen(forceOpen);
  }, [forceOpen]);

  // Initialize Session ID & Fetch Plugins (if not provided)
  useEffect(() => {
    // 1. Session Logic
    let storedSessionId = localStorage.getItem('bibichat_session_id');
    if (!storedSessionId) {
        storedSessionId = Math.random().toString(36).substring(2) + Date.now().toString(36);
        localStorage.setItem('bibichat_session_id', storedSessionId);
    }
    setSessionId(storedSessionId);

    // 2. Plugins Logic
    if (!plugins) {
        const fetchPlugins = async () => {
            const p = await apiService.getPlugins(userId);
            setPlugins(p);

            // Auto Open Logic - Only if not forced (embed mode handles its own open state usually via button, but autoOpen can trigger it too)
            // NOTE: Embed mode auto-open is now handled in StandaloneChatWidget (App.tsx)
            if (p.autoOpen?.enabled && !isEmbed) {
                setTimeout(() => setIsOpen(true), p.autoOpen.delay * 1000);
            }
        };
        fetchPlugins();
    }
  }, [userId, isEmbed]);

  // Effect to scroll bottom
  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, isLoading, showLeadForm]);

  useEffect(() => {
    if (messages.length === 1 && messages[0].id === '1') {
      setMessages([{ ...messages[0], text: settings.welcomeMessage }]);
    }
  }, [settings.welcomeMessage]);

  // Handle Auto-show Lead Form when opened
  useEffect(() => {
      if (isOpen && plugins?.leadForm?.enabled && plugins?.leadForm?.trigger === 'on_open' && !leadSubmitted && !showLeadForm) {
          setShowLeadForm(true);
      }
  }, [isOpen, plugins]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: Message = { id: Date.now().toString(), role: 'user', text: input, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      const responseText = await apiService.chat(userId, input, settings.botName, sessionId);
      const botMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', text: responseText, timestamp: Date.now() };
      setMessages(prev => [...prev, botMsg]);
    } catch (e) {
      setMessages(prev => [...prev, { id: 'err', role: 'model', text: "Hệ thống đang bận. Vui lòng thử lại sau.", timestamp: Date.now() }]);
    } finally {
      setIsLoading(false);
    }
  };

  const submitLead = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!leadForm.name || !leadForm.phone) return;
      await apiService.submitLead(userId, leadForm.name, leadForm.phone, leadForm.email);
      setLeadSubmitted(true);
      setShowLeadForm(false);
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'model', text: "Cảm ơn bạn! Chúng mình sẽ liên hệ sớm nha.", timestamp: Date.now() }]);
  };

  const handleToggle = () => {
      if (onClose) {
          onClose();
      } else {
          setIsOpen(!isOpen);
      }
  };

  // --- EMBEDDED MODE RENDER ---
  if (isEmbed) {
      // Specialized Render for Embed Iframe (Full Height/Width of container)
      return (
        <div className="w-full h-full bg-white rounded-2xl sm:rounded-3xl shadow-2xl overflow-hidden flex flex-col border border-slate-100/50">
          {/* Header */}
          <div className="p-4 text-white relative overflow-hidden shrink-0" style={{ backgroundColor: settings.primaryColor }}>
            <div className="absolute top-0 right-0 p-4 opacity-10">
               <i className="fa-solid fa-robot text-6xl"></i>
            </div>

            <div className="flex justify-between items-center relative z-10">
                <div className="flex items-center space-x-3">
                    <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center border-2 border-white/30 backdrop-blur-sm">
                        <i className="fa-solid fa-robot text-lg"></i>
                    </div>
                    <div>
                        <h3 className="font-bold text-base">{settings.botName}</h3>
                        <div className="flex items-center text-[10px] opacity-90 font-medium bg-white/20 px-2 py-0.5 rounded-full w-fit mt-0.5">
                        <span className="w-1.5 h-1.5 bg-emerald-400 rounded-full mr-1.5 animate-pulse"></span>
                        Trực tuyến
                        </div>
                    </div>
                </div>

                <div className="flex items-center gap-2">
                    {/* Social Plugin Icons for Embed Mode */}
                    {plugins?.social?.enabled && (
                        <div className="flex gap-2 mr-2">
                             {plugins.social.phone && (
                                 <a href={`tel:${plugins.social.phone}`} className="w-8 h-8 rounded-full bg-white/20 hover:bg-white/40 flex items-center justify-center transition-colors border border-white/20" title="Gọi Hotline" target="_blank" rel="noreferrer">
                                     <i className="fa-solid fa-phone text-xs"></i>
                                 </a>
                             )}
                             {plugins.social.zalo && (
                                 <a href={`https://zalo.me/${plugins.social.zalo}`} target="_blank" rel="noreferrer" className="w-8 h-8 rounded-full bg-white/20 hover:bg-white/40 flex items-center justify-center transition-colors border border-white/20" title="Chat Zalo">
                                     <div className="font-bold text-[8px]">Zalo</div>
                                 </a>
                             )}
                        </div>
                    )}

                    {/* Close Button for Embed */}
                    <button onClick={handleToggle} className="w-8 h-8 rounded-full bg-white/20 hover:bg-white/40 flex items-center justify-center transition-colors">
                        <i className="fa-solid fa-xmark text-sm"></i>
                    </button>
                </div>
            </div>
          </div>

          {/* Messages Area */}
          <div ref={scrollRef} className="flex-1 p-5 bg-slate-50 space-y-4 overflow-y-auto relative no-scrollbar">
            {messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] px-4 py-3 text-sm font-medium shadow-sm leading-relaxed ${
