                        <div className="flex items-center text-[10px] opacity-90 font-medium bg-white/20 px-2 py-0.5 rounded-full w-fit mt-0.5">
                        <span className="w-1.5 h-1.5 bg-emerald-400 rounded-full mr-1.5 animate-pulse"></span>
