        document.documentElement.style.backgroundColor = 'transparent';

        // Load settings
        const SERVER_URL = process.env.SERVER_URL || 'https://fuzzy-cosette-filezingme-org-64d51f5d.koyeb.app';
        fetch(`${SERVER_URL}/api/settings/${embedUserId}`)
            .then(r => r.json())
